out<-"analysis/gamewell_secondary_ls_2026-10-16";input<-"analysis/gamewell_interval_dataset_2026-10-15/gamewell_daily_intervals.csv.gz";pdir<-"analysis/gamewell_analysis_plan_2026-10-15"
for(pkg in c("lme4","lmerTest","clubSandwich"))if(!requireNamespace(pkg,quietly=TRUE))stop(paste("Missing package; no installation attempted:",pkg))
if(!all(read.csv(file.path(out,"PREFIT_HASH_CHECKS.csv"),stringsAsFactors=FALSE)$match))stop("Hash gate did not pass.");g<-read.csv(file.path(out,"PREFIT_COHORT_GATE.csv"),stringsAsFactors=FALSE);if(!all(g$match[!is.na(g$match)]))stop("Cohort gate failed.")
for(nm in c("RESULTS.csv","FIXED_EFFECTS.csv","CR2_FIXED_EFFECTS.csv","FIT_STATUS.csv","FIT_ERRORS.csv","sessionInfo.txt","life_satisfaction_fit1.rds","life_satisfaction_fit2.rds"))if(file.exists(file.path(out,nm)))stop(paste("Refusing to overwrite:",nm))
d<-read.csv(gzfile(input),stringsAsFactors=FALSE,check.names=FALSE);linked<-function(x)tolower(trimws(as.character(x)))%in%c("true","1","yes");base_ok<-(linked(d$xbox_linked)|linked(d$nintendo_linked))&!is.na(d$interval_duration_hours)&d$interval_duration_hours<=48&!is.na(d$prior_life_satisfaction)&!is.na(d$later_life_satisfaction)&!is.na(d$recorded_linked_console_minutes_unique);base<-d[base_ok,,drop=FALSE]
prep<-function(x){x$participant<-factor(as.character(x$participant_id));x$later_ls<-x$later_life_satisfaction;x$exposure_hours<-x$recorded_linked_console_minutes_unique/60;x$exposure_between<-ave(x$exposure_hours,x$participant,FUN=mean);x$exposure_within<-x$exposure_hours-x$exposure_between;x$prior_between<-ave(x$prior_life_satisfaction,x$participant,FUN=mean);x$prior_within<-x$prior_life_satisfaction-x$prior_between;x$log_interval_c<-log(x$interval_duration_hours)-mean(log(x$interval_duration_hours));x}
cohorts<-list(full=prep(base),no_zero=prep(base[base$prior_life_satisfaction!=0&base$later_life_satisfaction!=0,,drop=FALSE]))
result_cols<-c("fit_id","cohort_definition","n_intervals","n_participants","estimate_exposure_within","SE","Satterthwaite_df","model_CI_lower","model_CI_upper","CR2_SE","CR2_df","CR2_CI_lower","CR2_CI_upper","wider_CI_lower","wider_CI_upper","wider_source","exposure_within_SD","estimate_per_1SD_exposure","within_person_life_satisfaction_SD","estimate_per_within_person_LS_SD","SESOI_points_per_hour","category","convergence_code","convergence_messages","singular_fit","random_intercept_SD","residual_SD","ICC")
write.csv(as.data.frame(setNames(replicate(length(result_cols),character(),simplify=FALSE),result_cols)),file.path(out,"RESULTS.csv"),row.names=FALSE);write.csv(data.frame(fit_id=character(),error=character()),file.path(out,"FIT_ERRORS.csv"),row.names=FALSE);fx_all<-list();cr_all<-list();fx_n<-0L;cr_n<-0L;status_all<-list()
catfun<-function(lo,hi){if(!is.finite(lo)||!is.finite(hi))NA_character_ else if(lo>-.5&&hi<.5)"a"else if((hi<0||lo>0)&&(lo<-.5||hi>.5))"b"else if((hi<0||lo>0)&&lo>=-.5&&hi<=.5)"c"else"d"}
appendrow<-function(file,row){write.table(row,file,sep=",",row.names=FALSE,col.names=FALSE,append=TRUE,quote=TRUE,na="")}
for(k in seq_along(cohorts)){id<-if(k==1L)"fit1_full"else"fit2_exclude_zero";x<-cohorts[[k]];rds<-file.path(out,paste0("life_satisfaction_",id,".rds"));form<-later_ls~exposure_within+exposure_between+prior_within+prior_between+log_interval_c+(1|participant)
 fit<-tryCatch(lmerTest::lmer(form,data=x,REML=TRUE),error=function(e){msg<-conditionMessage(e);appendrow(file.path(out,"FIT_ERRORS.csv"),data.frame(fit_id=id,error=msg));stop(paste0("Fit ",id," failed; stopping without substitute: ",msg),call.=FALSE)})
 saveRDS(fit,rds)
 cf<-summary(fit)$coefficients;terms<-rownames(cf);model_fx<-data.frame(fit_id=id,term=terms,estimate=cf[,"Estimate"],SE=cf[,"Std. Error"],Satterthwaite_df=cf[,"df"],t=cf[,"t value"],p=cf[,"Pr(>|t|)"],CI_lower=cf[,"Estimate"]-qt(.975,cf[,"df"])*cf[,"Std. Error"],CI_upper=cf[,"Estimate"]+qt(.975,cf[,"df"])*cf[,"Std. Error"],stringsAsFactors=FALSE)
 crtest<-as.data.frame(clubSandwich::coef_test(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));crci<-as.data.frame(clubSandwich::conf_int(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));cterms<-if("Coef"%in%names(crtest))as.character(crtest$Coef)else rownames(crtest);citems<-if("Coef"%in%names(crci))as.character(crci$Coef)else rownames(crci);crsecol<-intersect(c("SE","Std. Error"),names(crtest))[1];crdfcol<-intersect(c("df_Satt","df"),names(crtest))[1];crlcol<-intersect(c("CI_L","lower"),names(crci))[1];crucol<-intersect(c("CI_U","upper"),names(crci))[1];if(any(is.na(c(crsecol,crdfcol,crlcol,crucol))))stop("Unexpected clubSandwich output columns; fit object saved, stopping.")
 cr_all_terms<-data.frame(fit_id=id,term=cterms,CR2_SE=as.numeric(crtest[[crsecol]]),CR2_df=as.numeric(crtest[[crdfcol]]),CR2_CI_lower=as.numeric(crci[[crlcol]][match(cterms,citems)]),CR2_CI_upper=as.numeric(crci[[crucol]][match(cterms,citems)]),stringsAsFactors=FALSE)
 i<-match("exposure_within",terms);j<-match("exposure_within",cterms);b<-model_fx$estimate[i];se<-model_fx$SE[i];df<-model_fx$Satterthwaite_df[i];ml<-model_fx$CI_lower[i];mu<-model_fx$CI_upper[i];cl<-cr_all_terms$CR2_CI_lower[j];cu<-cr_all_terms$CR2_CI_upper[j];widercr<-(cu-cl)>(mu-ml);wl<-if(widercr)cl else ml;wu<-if(widercr)cu else mu;xs<-sd(x$exposure_within);ys<-sd(x$later_ls-ave(x$later_ls,x$participant,FUN=mean));vc<-as.data.frame(lme4::VarCorr(fit));ri<-vc$sdcor[vc$grp=="participant"&vc$var1=="(Intercept)"][1];rs<-sigma(fit);icc<-ri^2/(ri^2+rs^2);cc<-fit@optinfo$conv$opt;messages<-fit@optinfo$conv$lme4$messages;msg<-if(length(messages))paste(as.character(messages),collapse=" | ")else if(length(cc)&&any(cc!=0))paste("optimizer code",paste(cc,collapse=","))else"none";sing<-lme4::isSingular(fit,tol=1e-4);catg<-catfun(wl,wu)
 row<-data.frame(fit_id=id,cohort_definition=if(k==1L)"linked; complete life satisfaction endpoints; interval <=48h"else"same cohort excluding intervals with zero at either life-satisfaction endpoint",n_intervals=nrow(x),n_participants=nlevels(x$participant),estimate_exposure_within=b,SE=se,Satterthwaite_df=df,model_CI_lower=ml,model_CI_upper=mu,CR2_SE=cr_all_terms$CR2_SE[j],CR2_df=cr_all_terms$CR2_df[j],CR2_CI_lower=cl,CR2_CI_upper=cu,wider_CI_lower=wl,wider_CI_upper=wu,wider_source=if(widercr)"CR2"else"model-based",exposure_within_SD=xs,estimate_per_1SD_exposure=b*xs,within_person_life_satisfaction_SD=ys,estimate_per_within_person_LS_SD=b/ys,SESOI_points_per_hour=.5,category=catg,convergence_code=paste(cc,collapse=","),convergence_messages=msg,singular_fit=sing,random_intercept_SD=ri,residual_SD=rs,ICC=icc,stringsAsFactors=FALSE);appendrow(file.path(out,"RESULTS.csv"),row)
 fx_n<-fx_n+1L;fx_all[[fx_n]]<-model_fx;cr_n<-cr_n+1L;cr_all[[cr_n]]<-merge(crtest,data.frame(term=cterms),by.x=if("Coef"%in%names(crtest))"Coef"else"row.names",by.y="term",all.x=TRUE,sort=FALSE)
 status_all[[k]]<-data.frame(fit_id=id,convergence_code=paste(cc,collapse=","),convergence_messages=msg,singular_fit=sing,random_intercept_SD=ri,residual_SD=rs,ICC=icc,n_intervals=nrow(x),n_participants=nlevels(x$participant),stringsAsFactors=FALSE)
 cat("Completed",id,"with",nrow(x),"intervals and",nlevels(x$participant),"participants.\n")
}
write.csv(do.call(rbind,fx_all),file.path(out,"FIXED_EFFECTS.csv"),row.names=FALSE);write.csv(do.call(rbind,status_all),file.path(out,"FIT_STATUS.csv"),row.names=FALSE)
# Export full CR2 inference by term from saved model calculations already held above.
cr_rows<-list();ncr<-0L;for(k in seq_along(cohorts)){id<-if(k==1L)"fit1_full"else"fit2_exclude_zero";fit<-readRDS(file.path(out,paste0("life_satisfaction_",id,".rds")));x<-cohorts[[k]];ct<-as.data.frame(clubSandwich::coef_test(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));ci<-as.data.frame(clubSandwich::conf_int(fit,vcov="CR2",cluster=x$participant,test="Satterthwaite"));tt<-if("Coef"%in%names(ct))as.character(ct$Coef)else rownames(ct);ti<-if("Coef"%in%names(ci))as.character(ci$Coef)else rownames(ci);sc<-intersect(c("SE","Std. Error"),names(ct))[1];dc<-intersect(c("df_Satt","df"),names(ct))[1];lc<-intersect(c("CI_L","lower"),names(ci))[1];uc<-intersect(c("CI_U","upper"),names(ci))[1];ncr<-ncr+1L;cr_rows[[ncr]]<-data.frame(fit_id=id,term=tt,estimate=as.numeric(ct$beta),CR2_SE=as.numeric(ct[[sc]]),CR2_df=as.numeric(ct[[dc]]),CR2_CI_lower=as.numeric(ci[[lc]][match(tt,ti)]),CR2_CI_upper=as.numeric(ci[[uc]][match(tt,ti)]),stringsAsFactors=FALSE)};write.csv(do.call(rbind,cr_rows),file.path(out,"CR2_FIXED_EFFECTS.csv"),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(out,"sessionInfo.txt"),useBytes=TRUE);cat("Both prespecified life-satisfaction fits completed once.\n")